/* DWARF original prototype: LPITEM RemoveFromCharacter(CItem * this) */

LPITEM __thiscall CItem::RemoveFromCharacter(CItem *this)

{
                    /* Unresolved local var: LPCHARACTER pOwner@[???] */
  if (this->m_pOwner == (CHARACTER *)0x0) {
    _sys_err("RemoveFromCharacter",0xeb,"Item::RemoveFromCharacter owner null");
  }
  else {
    if (this->m_bEquipped == false) {
      if ((this->m_bWindow != '\x03') && (this->m_bWindow != '\x04')) {
        if (this->m_bCell < 0x5a) {
          CHARACTER::SetItem(this->m_pOwner,this->m_bCell,(LPITEM)0x0);
        }
        else {
          _sys_err("RemoveFromCharacter",0xff,"CItem::RemoveFromCharacter: pos >= INVENTORY_MAX_NUM"
                  );
        }
      }
      this->m_pOwner = (LPCHARACTER)0x0;
      this->m_bCell = '\0';
    }
    else {
      Unequip(this);
    }
    this->m_bWindow = '\0';
    Save(this);
  }
  return this;
}
